"""Load the user's pre-built reference index JSON (never generated by this tool).

``load_reference_index(path)`` reads the file with its real field names. Keys this tool does
not interpret (provenance, counts, bookkeeping) are moved into the level's ``extras`` dict
(EXTRA_KEYS) so nothing is lost. Any other unknown key, or a missing required field, is an
InputAssetError naming the file and the field path (e.g. ``tables.0.columns.2.colour``).

Mode: a reference index given (``--reference-index`` or ``inputs.reference_index_file``) ->
grounded; none -> ungrounded (logged).
"""

from __future__ import annotations

import hashlib
import json
import logging
from pathlib import Path
from typing import Any

from pydantic import ValidationError

from synthetic_user.core.exceptions import InputAssetError, format_validation_error
from synthetic_user.models.reference import ReferenceIndex
from synthetic_user.models.run import GenerationMode

Logger = logging.Logger | logging.LoggerAdapter[logging.Logger]

# Per level: keys kept verbatim in ``extras`` (seen in the real file; not used by the tool).
EXTRA_KEYS: dict[str, frozenset[str]] = {
    "index": frozenset(
        {
            "generation_mode",
            "llm_provider",
            "llm_model",
            "source_files",
            "scope",
            "integrity_report",
        }
    ),
    "table": frozenset({"business_domain", "grain_status", "column_count"}),
    "column": frozenset({"foreign_key_raw", "semantic_roles"}),
    "relationship": frozenset({"source"}),
    "metric": frozenset(),
    "dimension": frozenset(),
    "time_column": frozenset(),
}
# Set by this loader / the model, so the file must not carry them.
_RESERVED = frozenset({"extras", "content_fingerprint"})


def load_reference_index(path: Path) -> ReferenceIndex:
    if not path.is_file():
        raise InputAssetError(f"Reference index not found: {path}")
    try:
        raw = path.read_bytes()
    except OSError as exc:
        raise InputAssetError(f"Cannot read reference index {path}: {exc}") from exc
    return parse_reference_index(raw, source=str(path))


def parse_reference_index(raw: bytes | str, *, source: str) -> ReferenceIndex:
    """Like load_reference_index, for uploaded content."""
    data_bytes = raw.encode("utf-8") if isinstance(raw, str) else raw
    try:
        data = json.loads(data_bytes)
    except ValueError as exc:
        raise InputAssetError(f"Reference index {source} is not valid JSON: {exc}") from exc
    if not isinstance(data, dict):
        raise InputAssetError(f"Reference index {source} must contain a JSON object")
    reserved = _reserved_keys(data)
    if reserved:
        raise InputAssetError(
            f"Reference index {source}: reserved field(s) {reserved} must not be in the file"
        )
    shaped = _with_extras(data)
    shaped["content_fingerprint"] = hashlib.sha256(data_bytes).hexdigest()[:8]
    try:
        return ReferenceIndex.model_validate(shaped)
    except ValidationError as exc:
        raise InputAssetError(
            f"Reference index {source} failed validation: {format_validation_error(exc)}"
        ) from exc


def resolve_mode(reference_index_path: Path | None, logger: Logger) -> GenerationMode:
    """grounded when a reference index path is given, else ungrounded (logged either way)."""
    if reference_index_path is None:
        logger.info("No reference index given: mode ungrounded (no cheat sheet, generic checks)")
        return GenerationMode.UNGROUNDED
    logger.info("Reference index %s: mode grounded", reference_index_path)
    return GenerationMode.GROUNDED


def load_optional_reference_index(
    reference_index_path: Path | None, logger: Logger
) -> ReferenceIndex | None:
    """Resolve the mode, then load the index when grounded."""
    if resolve_mode(reference_index_path, logger) is GenerationMode.UNGROUNDED:
        return None
    assert reference_index_path is not None
    return load_reference_index(reference_index_path)


# --- shaping ------------------------------------------------------------------------------------


def _split(node: Any, level: str) -> Any:
    if not isinstance(node, dict):
        return node  # wrong type: left for model validation to report with its path
    keys = EXTRA_KEYS[level]
    extras = {k: v for k, v in node.items() if k in keys}
    kept = {k: v for k, v in node.items() if k not in keys}
    return {**kept, "extras": extras} if extras else kept


def _split_list(nodes: Any, level: str) -> Any:
    return [_split(n, level) for n in nodes] if isinstance(nodes, list) else nodes


def _with_extras(data: dict[str, Any]) -> dict[str, Any]:
    shaped = _split(data, "index")
    shaped["relationships"] = _split_list(shaped.get("relationships", []), "relationship")
    tables = shaped.get("tables")
    if isinstance(tables, list):
        shaped["tables"] = [_shape_table(t) for t in tables]
    return dict(shaped)


def _shape_table(table: Any) -> Any:
    shaped = _split(table, "table")
    if not isinstance(shaped, dict):
        return shaped
    for key, level in (
        ("columns", "column"),
        ("relationships", "relationship"),
        ("metrics", "metric"),
        ("dimensions", "dimension"),
        ("time_columns", "time_column"),
    ):
        if key in shaped:
            shaped[key] = _split_list(shaped[key], level)
    return shaped


def _reserved_keys(data: dict[str, Any]) -> list[str]:
    """Reserved keys anywhere in the file, as dotted paths."""
    found = [k for k in data if k in _RESERVED]
    containers: list[tuple[str, Any]] = [("relationships", data.get("relationships"))]
    tables = data.get("tables")
    if isinstance(tables, list):
        for i, table in enumerate(tables):
            if not isinstance(table, dict):
                continue
            found += [f"tables.{i}.{k}" for k in table if k in _RESERVED]
            for key in ("columns", "relationships", "metrics", "dimensions", "time_columns"):
                containers.append((f"tables.{i}.{key}", table.get(key)))
    for prefix, items in containers:
        if isinstance(items, list):
            for j, item in enumerate(items):
                if isinstance(item, dict):
                    found += [f"{prefix}.{j}.{k}" for k in item if k in _RESERVED]
    return found
